update lab_reservation
set idempotency_key = null,
    request_hash = null,
    idempotency_expires_at = null
where id = #{reservationId}
  and applicant_id = #{applicantId}
  and idempotency_key = #{idempotencyKey}
  and idempotency_expires_at <= #{now}
  and del_flag = '0'

mapper.select:
select count(1)
from lab_reservation r
where r.device_id = #{deviceId}
  and r.status in ('PENDING', 'APPROVED', 'CHECKED_OUT')
  and r.start_time < #{newEnd}
  and r.end_time > #{newStart}
  and (#{excludeReservationId} is null or r.id <> #{excludeReservationId})
  and r.del_flag = '0'

select 
from lab_reservation r
inner join lab_device d on d.id = r.device_id and d.del_flag = '0'
where r.del_flag = '0'
and (
    r.applicant_id = #{currentUserId}

        or

            1 = 1

                d.laboratory_id in

                    #{laboratoryId}


            1 = 0


)
and r.applicant_id = #{applicantId}
and r.device_id = #{deviceId}
and r.status = #{status}
and r.reservation_no = #{reservationNo}
and r.end_time > #{from}
and r.start_time < #{to}

    order by ${sort.column} ${sort.direction}
    order by r.create_time desc

select r.start_time as startTime, r.end_time as endTime, r.status as reservationStatus
from lab_reservation r
where r.device_id = #{deviceId}
  and r.status in ('PENDING', 'APPROVED', 'CHECKED_OUT')
  and r.start_time < #{to}
  and r.end_time > #{from}
  and r.del_flag = '0'
order by r.start_time asc

